!function(){"use strict";app.factory("transferenciaBodegaService",(function($injector){let mS=$injector.get("mainService"),fS=$injector.get("formulario"),url="TransferenciaBodega/";return{getAll:getAll,insert:insert,update:update,anular:anular,getId:getId};function getAll(query){return mS.getData("get",`${url}Get?json=${JSON.stringify(query)}`,null,!0).then(response=>{if("0"==response.code)throw response;if("1"==response.code){let results;return(JSON.parse(response.payload)||[]).map(item=>({idTransferenciaBodega:item.idTransferenciaBodega,idTipoDocumento:item.idTipoDocumento,nroDoc:item.nroDoc,fechaEmision:item.fechaEmision,estadoDesc:item.estadoDesc,estadoCodigo:item.estadoCodigo,total:item.total,bodegaOrigen:item.bodegaOrigen,bodegaDestino:item.bodegaDestino,rowColor:item.rowColor,codEstab:item.codEstab}))}}).catch(err=>{throw err})}function insert(query){return mS.getData("post",`${url}`,query,!0).then(response=>{if("0"==response.code)throw response;return response}).catch(err=>{throw err})}function update(id,query){return mS.getData("put",`${url}?id=`+id,query,!0).then(response=>{if("0"==response.code)throw response;return response}).catch(err=>{throw err})}function anular(id){return mS.getData("delete",`${url}?id=`+id,null,!0).then(response=>response).catch(err=>{throw err})}}))}(window.angular);